def transform(content: str) -> str:
    if "Дайджест Агента-Искателя — слот 2026-11-01 21:40" in content:
        return content
    marker = "---\n\n"
    idx = content.find(marker)
    if idx == -1:
        return BLOCK + content
    pos = idx + len(marker)
    return content[:pos] + BLOCK + content[pos:]


shutil.copy2(TB, BAK)
with TextbookLock(TB) as lock:
    old = lock.read()
    new = transform(old)
    if new == old:
        print("УЖЕ ЗАПИСАНО — без изменений")
    else:
        lock.write(new)
        print("ЗАПИСАНО, +%d символов" % (len(new) - len(old)))
print("бэкап:", BAK)
